CREATE TABLE qpr_suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,code text NOT NULL,name text NOT NULL,tax_code text,contact jsonb,category text,rating numeric(5,2),status text NOT NULL DEFAULT 'active',bank_info jsonb,accounting_contact_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,code));
CREATE INDEX qpr_suppliers_org_idx ON qpr_suppliers(org_id);
CREATE TABLE qpr_supplier_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,supplier_id uuid NOT NULL REFERENCES qpr_suppliers(id),name text NOT NULL,role text,phone text,email text,is_primary boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX qpr_supplier_contacts_org_idx ON qpr_supplier_contacts(org_id,supplier_id);
CREATE TABLE qpr_purchase_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,request_no text NOT NULL,requester_id uuid NOT NULL,requester_dept_id uuid,purpose text NOT NULL DEFAULT 'resale',total_estimate numeric(20,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'draft',approval_route text,workflow_instance_id uuid,submitted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,request_no)); CREATE INDEX qpr_purchase_requests_org_idx ON qpr_purchase_requests(org_id,status);
CREATE TABLE qpr_purchase_request_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,purchase_request_id uuid NOT NULL REFERENCES qpr_purchase_requests(id),item_id uuid,product_name text NOT NULL,qty numeric(20,4) NOT NULL,uom text,est_price numeric(20,2) NOT NULL DEFAULT 0,suggested_supplier_id uuid,note text); CREATE INDEX qpr_purchase_request_lines_org_idx ON qpr_purchase_request_lines(org_id,purchase_request_id);
CREATE TABLE qpr_supplier_quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,purchase_request_id uuid NOT NULL REFERENCES qpr_purchase_requests(id),supplier_id uuid NOT NULL REFERENCES qpr_suppliers(id),price numeric(20,2) NOT NULL,content text,duration text,valid_until date,selected boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,purchase_request_id,supplier_id)); CREATE INDEX qpr_supplier_quotes_org_idx ON qpr_supplier_quotes(org_id,purchase_request_id);
CREATE TABLE qpr_supplier_evaluations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,supplier_id uuid NOT NULL REFERENCES qpr_suppliers(id),period text NOT NULL,criteria jsonb NOT NULL DEFAULT '{}'::jsonb,score numeric(5,2) NOT NULL,status text NOT NULL DEFAULT 'draft',evaluated_by uuid,evaluated_at timestamptz,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX qpr_supplier_evaluations_org_idx ON qpr_supplier_evaluations(org_id,supplier_id);
CREATE TABLE qpr_purchase_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,purchase_request_id uuid NOT NULL REFERENCES qpr_purchase_requests(id),supplier_id uuid REFERENCES qpr_suppliers(id),po_no text NOT NULL,contract_no text,order_date date,expected_delivery date,total_amount numeric(20,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'ordered',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,po_no)); CREATE INDEX qpr_purchase_orders_org_idx ON qpr_purchase_orders(org_id,purchase_request_id);
CREATE TABLE qpr_purchase_order_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,purchase_order_id uuid NOT NULL REFERENCES qpr_purchase_orders(id),item_id uuid,product_name text NOT NULL,qty numeric(20,4) NOT NULL,uom text,unit_price numeric(20,2) NOT NULL,amount numeric(20,2) NOT NULL); CREATE INDEX qpr_purchase_order_lines_org_idx ON qpr_purchase_order_lines(org_id,purchase_order_id);
CREATE TABLE qpr_goods_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,purchase_order_id uuid NOT NULL REFERENCES qpr_purchase_orders(id),receipt_no text NOT NULL,received_by uuid,qc_result text NOT NULL DEFAULT 'ok',receipt_doc_no text,received_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'recorded',UNIQUE(org_id,receipt_no)); CREATE INDEX qpr_goods_receipts_org_idx ON qpr_goods_receipts(org_id,purchase_order_id);
CREATE TABLE qpr_goods_receipt_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,goods_receipt_id uuid NOT NULL REFERENCES qpr_goods_receipts(id),purchase_order_line_id uuid,item_id uuid,qty_received numeric(20,4) NOT NULL,qc_note text); CREATE INDEX qpr_goods_receipt_lines_org_idx ON qpr_goods_receipt_lines(org_id,goods_receipt_id);
CREATE TABLE qpr_bid_projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,title text NOT NULL,proposal_by uuid,status text NOT NULL DEFAULT 'proposed',estimated_value numeric(20,2) NOT NULL DEFAULT 0,workflow_instance_id uuid,submit_deadline timestamptz,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX qpr_bid_projects_org_idx ON qpr_bid_projects(org_id,status);
CREATE TABLE qpr_bid_bidders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,bid_project_id uuid NOT NULL REFERENCES qpr_bid_projects(id),supplier_id uuid REFERENCES qpr_suppliers(id),bid_amount numeric(20,2),status text NOT NULL DEFAULT 'invited'); CREATE INDEX qpr_bid_bidders_org_idx ON qpr_bid_bidders(org_id,bid_project_id);
CREATE TABLE qpr_bid_evaluations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,bid_project_id uuid NOT NULL REFERENCES qpr_bid_projects(id),bidder_id uuid REFERENCES qpr_bid_bidders(id),criteria jsonb NOT NULL DEFAULT '{}'::jsonb,score numeric(5,2),decision text,evaluated_by uuid,evaluated_at timestamptz); CREATE INDEX qpr_bid_evaluations_org_idx ON qpr_bid_evaluations(org_id,bid_project_id);
CREATE TABLE qpr_procurement_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,building_id uuid,requested_by uuid,type text NOT NULL,items jsonb NOT NULL DEFAULT '[]'::jsonb,est_value numeric(20,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'draft',workflow_instance_id uuid,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX qpr_procurement_requests_org_idx ON qpr_procurement_requests(org_id,status);
CREATE TABLE qpr_service_acceptances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,procurement_request_id uuid REFERENCES qpr_procurement_requests(id),supplier_id uuid REFERENCES qpr_suppliers(id),result text NOT NULL DEFAULT 'ok',issue_desc text,escalated_to uuid,signed_by uuid,signed_at timestamptz); CREATE INDEX qpr_service_acceptances_org_idx ON qpr_service_acceptances(org_id,procurement_request_id);
